        internal static Dictionary<string, string> CreateSimplifiedDirections()
        {
            return CreateDirections("后");
        }

        internal static Dictionary<string, string> CreateTraditionalDirections()
        {
            return CreateDirections("後");
        }

        private static Dictionary<string, string> CreateDirections(string back)
        {
            return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
            {
                { "TOP", "上" },
                { "UP", "上" },
                { "RIGHT", "右" },
                { "BOTTOM", "下" },
                { "DOWN", "下" },
                { "LEFT", "左" },
                { "FORWARD", "前" },
                { "BACK", back },
            };
        }

